function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 1000) return 'nums1 needs 1 to 1000 values.';
  if (!Array.isArray(nums2) || nums2.length < 1 || nums2.length > 1000) return 'nums2 needs 1 to 1000 values.';
  const bad = v => !Number.isInteger(v) || v < 0 || v > 1000;
  if (nums1.some(bad) || nums2.some(bad)) return 'Each value is a whole number from 0 to 1000.';
  return null;
}

