function generate(rand, size) {
  const large = size === 'large';
  const length = () => large ? 500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const span = large ? [1001, 50, 1001][Math.floor(rand() * 3)] : [3, 6, 1001][Math.floor(rand() * 3)];
  const value = () => {
    if (!large && rand() < 0.1) return rand() < 0.5 ? 0 : 1000;
    return Math.floor(rand() * span);
  };
  const nums1 = Array.from({ length: length() }, value);
  const nums2 = Array.from({ length: length() }, value);
  return [nums1, nums2];
}
